import { describe, expect, it, vi } from 'vitest';

// The citations module is generated by vite.config.ts when the site is built.
vi.mock('virtual:source-citations', () => ({ sourceCitations: {} }));

const { summaryOf } = await import('#lib/server/glossary-entries.ts');
const { sectionWithSymbol } = await import('#lib/server/citations.ts');

describe('the summary a glossary hover card shows', () => {
	it('keeps the first sentence and drops citations', () => {
		const long =
			'An agency of the U.S. Department of the Interior that keeps the list of federally recognized Native nations';
		expect(summaryOf(`${long} [@source-key]. More text here.`)).toBe(`${long}.`);
	});

	it('adds a second sentence when the first is short', () => {
		expect(summaryOf('A short one. A second sentence follows it. A third.')).toBe(
			'A short one. A second sentence follows it.'
		);
	});

	it('turns a term link into its words', () => {
		expect(summaryOf('Short form of [[native-nations|Native nation]], used later.')).toBe(
			'Short form of Native nation, used later.'
		);
	});
});

describe('code sections in citations', () => {
	it('adds one section sign for one section and two for several', () => {
		expect(sectionWithSymbol('5130')).toBe('§ 5130');
		expect(sectionWithSymbol('471, 473')).toBe('§§ 471, 473');
	});
});
